import{_ as a,o as t,c as n,ae as s}from"./chunks/framework.EHGTsUvI.js";const u=JSON.parse('{"title":"Honey","description":"","frontmatter":{"title":"Honey"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/eggscrambler.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/eggscrambler.md"}'),o={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/eggscrambler.md"};function r(i,e,l,p,d,h){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="honey" tabindex="-1">Honey <a class="header-anchor" href="#honey" aria-label="Permalink to &quot;Honey&quot;">​</a></h1><p>Honey is an animal product produced by <strong>Bees</strong>. Bees are placed inside Beehives, where they produce Honey Frames that can be processed by the <strong>Honey Factory</strong> into Honey Barrels and Honey Pallets.</p><p>Honey is primarily a secondary income source and can also be used to produce <strong>Honey-Oatmeal</strong>.</p><h2 id="honey-information" tabindex="-1">Honey Information <a class="header-anchor" href="#honey-information" aria-label="Permalink to &quot;Honey Information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Main Source</td><td>Bees</td></tr><tr><td>Production Building</td><td>Honey Factory</td></tr><tr><td>Factory Price</td><td>80,000 Coins</td></tr><tr><td>Required License</td><td>Bee License</td></tr><tr><td>Product</td><td>Honey</td></tr><tr><td>Pallet Size</td><td>4 Barrels</td></tr><tr><td>Frames per Barrel</td><td>6</td></tr><tr><td>Frames per Pallet</td><td>24</td></tr></tbody></table><p>The Honey Factory converts Honey Frames produced by bees into Honey Barrels, with <strong>4 Barrels making up one Honey Pallet</strong>.</p><h2 id="required-equipment" tabindex="-1">Required Equipment <a class="header-anchor" href="#required-equipment" aria-label="Permalink to &quot;Required Equipment&quot;">​</a></h2><p>To begin producing Honey, you will need:</p><ul><li><strong>Bee License</strong></li><li><strong>Beehive</strong></li><li><strong>Bees</strong></li><li><strong>Honey Factory</strong></li><li><strong>Forklift</strong></li><li><strong>Pallet-capable vehicle or trailer</strong></li></ul><p>Honey is stored as pallets rather than a liquid product, so a forklift and suitable transport are important for moving finished Honey.</p><h2 id="bee-production" tabindex="-1">Bee Production <a class="header-anchor" href="#bee-production" aria-label="Permalink to &quot;Bee Production&quot;">​</a></h2><p>Bees produce Honey Frames while inside a Beehive.</p><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Honey per Bee</td><td>4 Frames</td></tr><tr><td>Production Time</td><td>15 Minutes</td></tr><tr><td>Frames per Barrel</td><td>6</td></tr><tr><td>Frames per Pallet</td><td>24</td></tr><tr><td>Barrels per Pallet</td><td>4</td></tr></tbody></table><p>For example, <strong>3 Bees</strong> producing 4 frames each will create:</p><p><strong>3 × 4 = 12 Honey Frames</strong></p><p>Those 12 frames are enough to produce <strong>2 Honey Barrels</strong>.</p><h2 id="how-to-produce-honey" tabindex="-1">How to Produce Honey <a class="header-anchor" href="#how-to-produce-honey" aria-label="Permalink to &quot;How to Produce Honey&quot;">​</a></h2><h3 id="_1-unlock-the-bee-license" tabindex="-1">1. Unlock the Bee License <a class="header-anchor" href="#_1-unlock-the-bee-license" aria-label="Permalink to &quot;1. Unlock the Bee License&quot;">​</a></h3><p>The Bee License is required before you can begin using the bee production system.</p><p>Bee-related progression is tied to the <strong>Bee Goals branch</strong>.</p><h3 id="_2-purchase-a-beehive" tabindex="-1">2. Purchase a Beehive <a class="header-anchor" href="#_2-purchase-a-beehive" aria-label="Permalink to &quot;2. Purchase a Beehive&quot;">​</a></h3><p>Purchase and place a Beehive on your farm.</p><p>A hive can house multiple Bees, with the starting capacity being <strong>2 Bees per hive</strong> according to the available documentation. Hive capacity can be increased through progression.</p><h3 id="_3-purchase-bees" tabindex="-1">3. Purchase Bees <a class="header-anchor" href="#_3-purchase-bees" aria-label="Permalink to &quot;3. Purchase Bees&quot;">​</a></h3><p>Bees can be purchased from <strong>AnimalCo</strong>.</p><p>Each Bee is placed inside a Beehive and begins producing Honey Frames. Current community documentation lists a Bee Box at <strong>15,000 Coins</strong>.</p><h3 id="_4-wait-for-the-bees" tabindex="-1">4. Wait for the Bees <a class="header-anchor" href="#_4-wait-for-the-bees" aria-label="Permalink to &quot;4. Wait for the Bees&quot;">​</a></h3><p>Bees take approximately <strong>15 minutes</strong> to produce Honey.</p><p>Each Bee produces <strong>4 Honey Frames</strong> during a production cycle.</p><h3 id="_5-collect-the-honey-frames" tabindex="-1">5. Collect the Honey Frames <a class="header-anchor" href="#_5-collect-the-honey-frames" aria-label="Permalink to &quot;5. Collect the Honey Frames&quot;">​</a></h3><p>Once the Bees have finished producing, collect the Honey Frames from the Beehive.</p><p>These frames are the raw material required by the Honey Factory.</p><h3 id="_6-process-the-honey" tabindex="-1">6. Process the Honey <a class="header-anchor" href="#_6-process-the-honey" aria-label="Permalink to &quot;6. Process the Honey&quot;">​</a></h3><p>Take the Honey Frames to the Honey Factory.</p><p>The conversion is:</p><p><strong>6 Honey Frames → 1 Honey Barrel</strong></p><p>A full Honey Pallet requires:</p><p><strong>24 Honey Frames → 4 Honey Barrels → 1 Honey Pallet</strong></p><h3 id="_7-transport-the-honey" tabindex="-1">7. Transport the Honey <a class="header-anchor" href="#_7-transport-the-honey" aria-label="Permalink to &quot;7. Transport the Honey&quot;">​</a></h3><p>Honey is stored as pallets, so use a <strong>Forklift</strong> to move the pallet onto a suitable flatbed vehicle or trailer.</p><p>Compatible vehicles include options such as the <strong>M2 Flatbed, M1 Flatbed, R350 Flatbed and Flatbed Hauler S-500</strong>.</p><h3 id="_8-sell-the-honey" tabindex="-1">8. Sell the Honey <a class="header-anchor" href="#_8-sell-the-honey" aria-label="Permalink to &quot;8. Sell the Honey&quot;">​</a></h3><p>Honey can be sold through the animal-product selling system at <strong>AnimalCo</strong>.</p><p>The older documented maximum was <strong>30,000 Coins per Honey Pallet</strong>, or <strong>7,500 Coins per Barrel</strong>. However, this price is explicitly marked as outdated in the source, so the current in-game selling price should be used instead.</p><h2 id="honey-production-chain" tabindex="-1">Honey Production Chain <a class="header-anchor" href="#honey-production-chain" aria-label="Permalink to &quot;Honey Production Chain&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bee License</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>  Beehive</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>    Bees</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>Honey Frames</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>Honey Factory</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>Honey Barrels</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>Honey Pallet</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>   AnimalCo</span></span></code></pre></div><h2 id="honey-oatmeal" tabindex="-1">Honey-Oatmeal <a class="header-anchor" href="#honey-oatmeal" aria-label="Permalink to &quot;Honey-Oatmeal&quot;">​</a></h2><p>Honey can also be used to produce <strong>Honey-Oatmeal</strong>.</p><p>The Honey-Oatmeal Factory uses <strong>1 Honey Pallet and harvested Oats</strong> to produce Honey-Oatmeal. A full Honey-Oatmeal pallet contains 27 bundles and has historically been listed at up to <strong>87,750 Coins</strong>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Honey Pallet ─────┐</span></span>
<span class="line"><span>                  ↓</span></span>
<span class="line"><span>              Oatmeal</span></span>
<span class="line"><span>                  ↑</span></span>
<span class="line"><span>                  │</span></span>
<span class="line"><span>Oats ─────────────┘</span></span></code></pre></div><blockquote><p><strong>Note:</strong> Honey is generally considered a secondary or specialised income source rather than a primary money-making method. It is particularly useful when progressing through Bee Goals or when combining Honey with Oats for Honey-Oatmeal.</p></blockquote>`,51)])])}const y=a(o,[["render",r]]);export{u as __pageData,y as default};
